{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Conflicting reports of increases and decreases in rates of preterm birth (PTB) and stillbirth in the general population during the coronavirus disease 2019 (COVID-­ 19) pandemic have surfaced.",
      "reason": "The abstract/introduction notes conflicting evidence (an uncertainty), and the Key Message describes current knowledge of pandemic effects on PTB and stillbirth, but a fuller account of existing knowledge appears mainly in the Discussion rather than a dedicated Introduction rationale."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "Further studies from countries with high prevalence are needed and this review will be updated periodically.",
      "reason": "The need for further evidence and a periodically updated review is stated in the Key Message, and the objective of a living systematic review is given in the abstract, but the importance/need for the review is not fully elaborated in the Introduction."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_19",
      "quote": "Recently, Chmielewska 59 et al reported results from a system-­ atic review and meta-­ analyses including studies evaluating studies assessing population-­ level impact during the pandemic period published up to January 8, 2021.",
      "reason": "A previous similar review (Chmielewska et al) is identified and cited, and differences from the current review explained, but only in the Discussion; this is not presented in the Introduction as the rationale for the current review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of pandemic-related changes in pregnancy outcomes (etiology/prognosis-type question), not a review of intervention effects, so no mechanism of action is required."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No complex intervention or delivery context is evaluated; the review examines population-level associations, so a logic model is not applicable."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The objective of our study was to conduct a living systematic review and meta-­ analyses of studies reporting pregnancy and neonatal outcomes by comparing the pandemic and pre-­ pandemic periods.",
      "reason": "The abstract's introduction explicitly states the review objective: a living systematic review and meta-analysis comparing pregnancy and neonatal outcomes between pandemic and pre-pandemic periods."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "studies reporting pregnancy and neonatal outcomes by comparing the pandemic and pre-­ pandemic periods",
      "reason": "The comparison (pandemic vs pre-pandemic) and outcomes (pregnancy and neonatal outcomes, e.g., PTB, stillbirth) are stated, but the population (P) is only implicitly defined (general population pregnancies) and no formal PICO framing is provided."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Studies were included if they compared pregnancy outcomes between the COVID-19 pandemic period and pre-pandemic time periods and reported on any of the outcomes of interest. We excluded studies that only reported outcomes of pregnant women with COVID-19.",
      "reason": "Eligibility is specified: comparative design (pandemic vs pre-pandemic periods), any study design, required outcomes of interest, and exclusion of COVID-19-infected-only populations; setting/population scope is further described via study characteristics."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "we searched PubMed and Embase databases... for studies published up to August 14, 2021... and included any type of study design published in the English language",
      "reason": "Report characteristics are specified: publication date limit (up to August 14, 2021) and English-language restriction."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Full-text articles excluded, with reasons (n = 27): Awaiting assessment (n = 9); Different outcome (n = 5); Different study objective (n = 5); Non-comparative studies (n = 4); Outcome of maternal infection (n = 2); No outcome data (n = 1); Editorial (n = 1)",
      "reason": "The PRISMA flow diagram (figure_6, chunk text_13) visually distinguishes exclusion for 'Different outcome' (outcome not measured) from 'No outcome data' (results not reported), satisfying this conditional element."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Post-hoc subgroup analyses were conducted for the two primary outcomes after dividing studies into single-center (or selected hospitals/centers in an area), regional (statewide or province-wide) or national in scope.",
      "reason": "Synthesis groups are specified: meta-analyses of pandemic vs pre-pandemic comparisons by outcome, plus subgroup groupings by study scope (single-center, regional, national) and meta-regression by pre-pandemic duration, linked to the review's comparison of pandemic vs pre-pandemic periods."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "As we were interested in overall pregnancy outcomes, we did not restrict studies based on plurality (including both singleton and multiple pregnancies).",
      "reason": "Rationale for the notable restriction (excluding COVID-19-only studies and not restricting by plurality) is provided; the Discussion (text_19) further explains the review was designed to evaluate population-level pandemic impact, not maternal COVID-19 itself."
    }
  ],
  "confidence": 88
}

{
