      "element_id": "prisma_2020_9_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_11",
      "quote": "Data from the eligible studies were independently extracted by two authors (JY and PS) using a predefined, standardized extraction form.",
      "reason": "Data extraction was performed manually by two authors using a predefined standardized form; no automation tools are reported or implied, so this conditional requirement does not apply."
